/** All papers whose unesco_principles column includes the given principle code
 * (e.g. "P02"). This is the single source of truth for paper-to-planet
 * membership — nothing here is classified or inferred, it's a direct filter
 * over the principles array read from the spreadsheet. */
export function getPapersForPrinciple(principleId: string): PrinciplePaper[] {
  return principlePapers.filter((p) => p.principles.includes(principleId));
}
